// Room "P0 west bedroom" (interior designer's part): the inner air is x3..4, z14..20, floor layer y5, feet y6, head
// room to y8. The door (5, 6..7, 16) opens onto the cell (4, 6, 16), which stays clear. The west wall (x2) is solid
// only at z16..18 (windows at z14..15 and z19..20), so the two beds take the heads there (x3, against x2), feet at
// x4, at z17 and z18. The room is 2 wide: a bed row cuts it, so the south pocket (z19..20) is a barrel dresser, and
// the north end (z14..15) is the walk-in: a barrel dresser under the north window and a lamp post.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  b: "barrel",
  f: "oak_fence",
  r: "red_carpet",
  p: "potted_poppy",
  l: ["lantern", { hanging: "false" }],
};

// bed() from the build library refuses a cell whose id is namespaced ("minecraft:air") as not air, so a loaded grid
// never gets a bed. This places the same two halves with the same states, testing air either way.
function placeBed(g, [x, y, z], facing, color) {
  const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] }[facing];
  const free = (x, y, z) => !g.get(x, y, z) || /air$/.test(g.get(x, y, z).block);
  const hx = x + STEP[0], hz = z + STEP[1];
  if (!free(x, y, z) || !free(hx, y, hz)) return false;
  g.set(x, y, z, `${color}_bed`, { facing, part: "foot", occupied: "false" });
  g.set(hx, y, hz, `${color}_bed`, { facing, part: "head", occupied: "false" });
  return true;
}

export function build(g) {
  // feet layer y6 (rows z14..20, columns x3..4): dressers, lamp post, rug (the beds are placed below)
  // head layer y7: the flower pot and lantern on the north dresser, the lanterns on the post and the south dresser
  layers(g, [3, 6, 14], LEGEND, [
    [
      "bb", // z14 dresser under the north window
      "f.", // z15 lamp post at x3; x4 stays the lane
      "..", // z16 lane: (4,6,16) is the door's first cell and stays clear
      "..", // z17 beds
      "..", // z18 beds
      "bb", // z19 south dresser
      "bb", // z20 south dresser
    ],
    [
      "pl", // z14 pot and lantern on the north dresser
      "l.", // z15 lantern on the lamp post
      "..", // z16
      "..", // z17
      "..", // z18
      "l.", // z19 lantern on the south dresser
      "..", // z20
    ],
  ]);

  // two beds: heads at x3 against the west wall (x2), feet at x4, pillow ends toward the wall
  placeBed(g, [4, 6, 17], "west", "red");
  placeBed(g, [4, 6, 18], "west", "blue");
}
