17	// never gets a bed. This places the same two halves with the same states, testing air either way.
18	function placeBed(g, [x, y, z], facing, color) {
19	  const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] }[facing];
20	  const free = (x, y, z) => !g.get(x, y, z) || /air$/.test(g.get(x, y, z).block);
