22	  if (!free(x, y, z) || !free(hx, y, hz)) return false;
23	  g.set(x, y, z, `${color}_bed`, { facing, part: "foot", occupied: "false" });
24	  g.set(hx, y, hz, `${color}_bed`, { facing, part: "head", occupied: "false" });
25	  return true;
26	}
